package kv

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"
)

// MaxValueBytes is the largest value accepted by PUT.
const MaxValueBytes = 1 << 20

const (
	maxKeyLen = 64
	kvPrefix  = "/kv/"
)

// Handler routes requests for the key-value API.
type Handler struct {
	store *Store
}

// NewHandler returns an http.Handler serving the API backed by store.
func NewHandler(store *Store) *Handler {
	return &Handler{store: store}
}

// ServeHTTP implements http.Handler. Routing is done by hand on the raw
// request path so that no path cleaning or unescaping alters the key.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.EscapedPath()
	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		writeBody(w, http.StatusOK, []byte("ok"))
	case path == "/kv":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		h.listKeys(w)
	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !validKey(key) {
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		switch r.Method {
		case http.MethodGet:
			h.getValue(w, key)
		case http.MethodPut:
			h.putValue(w, r, key)
		case http.MethodDelete:
			h.deleteValue(w, key)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodPut, http.MethodDelete)
		}
	default:
		w.WriteHeader(http.StatusNotFound)
	}
}

func (h *Handler) listKeys(w http.ResponseWriter) {
	body, err := json.Marshal(h.store.Keys())
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	writeBody(w, http.StatusOK, body)
}

func (h *Handler) getValue(w http.ResponseWriter, key string) {
	value, ok := h.store.Get(key)
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/octet-stream")
	writeBody(w, http.StatusOK, value)
}

func (h *Handler) putValue(w http.ResponseWriter, r *http.Request, key string) {
	if r.ContentLength > MaxValueBytes {
		w.WriteHeader(http.StatusRequestEntityTooLarge)
		return
	}
	value, err := io.ReadAll(http.MaxBytesReader(w, r.Body, MaxValueBytes))
	if err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			w.WriteHeader(http.StatusRequestEntityTooLarge)
		} else {
			w.WriteHeader(http.StatusBadRequest)
		}
		return
	}
	status := http.StatusOK
	if h.store.Put(key, value) {
		status = http.StatusCreated
	}
	w.Header().Set("Content-Length", "0")
	w.WriteHeader(status)
}

func (h *Handler) deleteValue(w http.ResponseWriter, key string) {
	if !h.store.Delete(key) {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func writeBody(w http.ResponseWriter, status int, body []byte) {
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
	w.Header().Set("Allow", strings.Join(allowed, ", "))
	w.WriteHeader(http.StatusMethodNotAllowed)
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > maxKeyLen {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

package kv

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
)

func do(t *testing.T, srv *httptest.Server, method, path string, body []byte) (int, http.Header, []byte) {
	t.Helper()
	var rd io.Reader
	if body != nil {
		rd = bytes.NewReader(body)
	}
	req, err := http.NewRequest(method, srv.URL+path, rd)
	if err != nil {
		t.Fatal(err)
	}
	req.Close = true
	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	return resp.StatusCode, resp.Header, b
}

func TestRoutes(t *testing.T) {
	srv := httptest.NewServer(NewHandler(NewStore()))
	defer srv.Close()

	long := strings.Repeat("a", 64)
	tests := []struct {
		method, path, body string
		status             int
		want               string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/kv", "", 200, "[]"},
		{"POST", "/kv", "", 405, ""},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/a", "1", 201, ""},
		{"PUT", "/kv/a", "11", 200, ""},
		{"GET", "/kv/a", "", 200, "11"},
		{"GET", "/kv", "", 200, `["a","b"]`},
		{"PUT", "/kv/" + long, "", 201, ""},
		{"GET", "/kv/" + long, "", 200, ""},
		{"GET", "/kv/" + long + "a", "", 400, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/a.b", "", 400, ""},
		{"GET", "/kv/%41", "", 400, ""},
		{"PATCH", "/kv/a", "", 405, ""},
		{"PATCH", "/kv/a.b", "", 400, ""},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/", "", 404, ""},
		{"GET", "/kvx", "", 404, ""},
		{"GET", "/health/", "", 404, ""},
	}
	for _, tc := range tests {
		var body []byte
		if tc.method == "PUT" {
			body = []byte(tc.body)
		}
		status, _, got := do(t, srv, tc.method, tc.path, body)
		if status != tc.status || string(got) != tc.want {
			t.Errorf("%s %s: got %d %q, want %d %q", tc.method, tc.path, status, got, tc.status, tc.want)
		}
	}
}

func TestLargeValues(t *testing.T) {
	srv := httptest.NewServer(NewHandler(NewStore()))
	defer srv.Close()

	value := make([]byte, MaxValueBytes)
	for i := range value {
		value[i] = byte(i * 7)
	}
	if status, _, _ := do(t, srv, "PUT", "/kv/big", value); status != 201 {
		t.Fatalf("PUT max value: status %d", status)
	}
	status, hdr, got := do(t, srv, "GET", "/kv/big", nil)
	if status != 200 || !bytes.Equal(got, value) || hdr.Get("Content-Length") != fmt.Sprint(MaxValueBytes) {
		t.Fatalf("GET max value: status %d, %d bytes", status, len(got))
	}
	if status, _, _ := do(t, srv, "PUT", "/kv/big2", append(value, 0)); status != 413 {
		t.Fatalf("PUT oversized value: status %d, want 413", status)
	}
}

func TestConcurrent(t *testing.T) {
	srv := httptest.NewServer(NewHandler(NewStore()))
	defer srv.Close()

	var wg sync.WaitGroup
	for i := range 128 {
		wg.Go(func() {
			key := fmt.Sprintf("k%03d", i)
			if status, _, _ := do(t, srv, "PUT", "/kv/"+key, []byte(key)); status != 201 {
				t.Errorf("PUT %s: status %d", key, status)
			}
			if _, _, got := do(t, srv, "GET", "/kv/"+key, nil); string(got) != key {
				t.Errorf("GET %s: %q", key, got)
			}
		})
	}
	wg.Wait()
	_, _, got := do(t, srv, "GET", "/kv", nil)
	if n := strings.Count(string(got), ","); n != 127 {
		t.Errorf("list has %d commas, want 127", n)
	}
}

// Package kv implements the in-memory key-value store and its HTTP API.
package kv

import (
	"slices"
	"sync"
)

// Store is a concurrency-safe in-memory map from keys to byte values.
type Store struct {
	mu      sync.RWMutex
	entries map[string][]byte
}

// NewStore returns an empty Store.
func NewStore() *Store {
	return &Store{entries: make(map[string][]byte)}
}

// Put stores value under key and reports whether the key was newly created.
// The store takes ownership of value; callers must not modify it afterwards.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.entries[key]
	s.entries[key] = value
	return !exists
}

// Get returns the value stored under key and whether it was present.
// The returned slice must not be modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.entries[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.entries[key]
	delete(s.entries, key)
	return ok
}

// Keys returns every key in ascending order.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.entries))
	for k := range s.entries {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

// Command kvhttp serves an in-memory key-value store over HTTP on 127.0.0.1.
//
// Usage:
//
//	app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/kv"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: app <port>")
		os.Exit(2)
	}
	port, err := strconv.ParseUint(os.Args[1], 10, 16)
	if err != nil {
		fmt.Fprintf(os.Stderr, "invalid port: %s\n", os.Args[1])
		os.Exit(2)
	}
	if err := run(net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10))); err != nil {
		log.Fatal(err)
	}
}

func run(addr string) error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	srv := &http.Server{
		Addr:              addr,
		Handler:           kv.NewHandler(kv.NewStore()),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       120 * time.Second,
		MaxHeaderBytes:    64 << 10,
	}

	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()

	select {
	case err := <-errc:
		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return err
	case <-ctx.Done():
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		return srv.Shutdown(shutdownCtx)
	}
}
